// Rest-pose skeleton. Everything downstream (SDF anatomy, clothing, skin weights)
// reads positions from here, so proportions are changed in exactly one place.
// Space: metres, Y up, character faces +Z. Feet on y = 0.
import * as THREE from 'three';

const L = 1, R = -1;

// name -> { parent, pos }.  `.L`/`.R` pairs are generated by mirror().
const SPEC = [
  ['root', null, [0, 0, 0]],
  ['hips', 'root', [0, 0.965, 0]],
  ['spine', 'hips', [0, 1.075, 0.01]],
  ['chest', 'spine', [0, 1.2, 0.005]],
  ['upperChest', 'chest', [0, 1.325, 0]],
  ['neckBase', 'upperChest', [0, 1.418, -0.008]],
  ['neck', 'neckBase', [0, 1.487, 0.004]],
  ['head', 'neck', [0, 1.578, 0.018]],
  ['headTop', 'head', [0, 1.702, 0.022]],
  ['jaw', 'head', [0, 1.604, 0.058]],
  ['jawTip', 'jaw', [0, 1.576, 0.247]],

  ['tail1', 'hips', [0, 0.985, -0.085]],
  ['tail2', 'tail1', [0, 0.925, -0.215]],
  ['tail3', 'tail2', [0, 0.83, -0.335]],
  ['tail4', 'tail3', [0, 0.7, -0.435]],
  ['tail5', 'tail4', [0, 0.555, -0.5]],
  ['tail6', 'tail5', [0, 0.415, -0.525]],
];

const MIRROR = [
  ['clavicle', 'upperChest', [0.045, 1.362, 0.015]],
  ['shoulder', 'clavicle', [0.176, 1.366, 0]],
  ['elbow', 'shoulder', [0.196, 1.105, -0.012]],
  ['wrist', 'elbow', [0.206, 0.856, 0.018]],
  ['hand', 'wrist', [0.207, 0.8, 0.012]],

  ['thumb1', 'hand', [0.196, 0.792, 0.048]],
  ['thumb2', 'thumb1', [0.19, 0.763, 0.074]],
  ['thumb3', 'thumb2', [0.187, 0.744, 0.091]],
  ['index1', 'hand', [0.207, 0.757, 0.042]],
  ['index2', 'index1', [0.208, 0.714, 0.048]],
  ['index3', 'index2', [0.208, 0.677, 0.052]],
  ['middle1', 'hand', [0.208, 0.756, 0.014]],
  ['middle2', 'middle1', [0.209, 0.711, 0.02]],
  ['middle3', 'middle2', [0.209, 0.672, 0.025]],
  ['ring1', 'hand', [0.207, 0.756, -0.013]],
  ['ring2', 'ring1', [0.208, 0.713, -0.007]],
  ['ring3', 'ring2', [0.208, 0.677, -0.002]],
  ['pinky1', 'hand', [0.205, 0.754, -0.039]],
  ['pinky2', 'pinky1', [0.205, 0.719, -0.034]],
  ['pinky3', 'pinky2', [0.205, 0.691, -0.03]],

  ['hip', 'hips', [0.088, 0.945, 0]],
  ['knee', 'hip', [0.098, 0.525, 0.015]],
  ['ankle', 'knee', [0.1, 0.1, -0.015]],
  ['toe', 'ankle', [0.1, 0.03, 0.105]],
];

function buildSpec() {
  const out = SPEC.map(([n, p, pos]) => ({ name: n, parent: p, pos }));
  for (const side of [L, R]) {
    const sfx = side === L ? '.L' : '.R';
    for (const [n, p, pos] of MIRROR) {
      const parent = MIRROR.some((m) => m[0] === p) ? p + sfx : p;
      out.push({ name: n + sfx, parent, pos: [pos[0] * side, pos[1], pos[2]] });
    }
  }
  return out;
}

export function createSkeleton() {
  const spec = buildSpec();
  const bones = [];
  const byName = new Map();
  const restPos = new Map();

  for (const s of spec) {
    const bone = new THREE.Bone();
    bone.name = s.name;
    byName.set(s.name, bone);
    restPos.set(s.name, s.pos);
    bones.push(bone);
  }
  for (const s of spec) {
    const bone = byName.get(s.name);
    if (s.parent) {
      const parent = byName.get(s.parent);
      parent.add(bone);
      const pp = restPos.get(s.parent);
      bone.position.set(s.pos[0] - pp[0], s.pos[1] - pp[1], s.pos[2] - pp[2]);
    } else {
      bone.position.set(...s.pos);
    }
  }

  const index = new Map();
  bones.forEach((b, i) => index.set(b.name, i));
  const skeleton = new THREE.Skeleton(bones);

  return {
    skeleton,
    bones,
    root: byName.get('root'),
    byName,
    index,
    restPos,
    /** children of a bone, by name */
    childrenOf(name) {
      return spec.filter((s) => s.parent === name).map((s) => s.name);
    },
    spec,
  };
}

/**
 * Skinning segments. Each bone owns the span from itself to its first child
 * (leaves get a short stub along the parent direction).
 * `tweaks` lets specific bones widen/narrow their pull.
 */
export function buildSegments(rig, tweaks = {}) {
  const segs = [];
  for (const s of rig.spec) {
    const kids = rig.childrenOf(s.name);
    const a = rig.restPos.get(s.name);
    let b;
    if (kids.length) {
      b = rig.restPos.get(kids[0]);
    } else {
      const pp = s.parent ? rig.restPos.get(s.parent) : [a[0], a[1] - 1, a[2]];
      b = [a[0] + (a[0] - pp[0]) * 0.4, a[1] + (a[1] - pp[1]) * 0.4, a[2] + (a[2] - pp[2]) * 0.4];
    }
    const t = tweaks[s.name] || {};
    segs.push({
      name: s.name,
      boneIndex: rig.index.get(s.name),
      a, b,
      bias: t.bias !== undefined ? t.bias : 1,
      reach: t.reach,
    });
  }
  return segs;
}
